# 2. OCR_Bench                                                                                                                                                                                                                        
# -------------------------------------------------------------------------                                                                                                                                                           
def prep_prompt_ocrbench(question_id: int, model_id: str) -> tuple[str, str]:                                                                                                                                                         
    """Prepares a prompt for OCR_Bench questions with an image."""                                                                                                                                                                    
    OCRBENCH_QUESTION_PATH = "/g/home/orachat.c/project/MLLM/TokenPacker/playground/data/eval/ocr_bench/OCRBench.json"                                                                                                                
    OCRBENCH_MODEL_ANS = f"/g/home/orachat.c/project/MLLM/TokenPacker/playground/data/eval/ocr_bench/{model_id}.json"                                                                                                                 
    image_root = "/g/home/orachat.c/project/MLLM/TokenPacker/playground/data/eval/ocr_bench/OCRBench_Images"                                                                                                                          
                                                                                                                                                                                                                                        
    question, image_path, model_answer = "", "", ""                                                                                                                                                                                   
    with open(OCRBENCH_QUESTION_PATH, "r") as f:                                                                                                                                                                                      
        ocr_data = json.load(f)                                                                                                                                                                                                       
        for item in ocr_data:                                                                                                                                                                                                         
            if item.get("id") == question_id:                                                                                                                                                                                         
                question = item["question"]                                                                                                                                                                                           
                image_path = f"{image_root}/{item['image_path']}"                                                                                                                                                                     
                break                                                                                                                                                                                                                 
                                                                                                                                                                                                                                        
    with open(OCRBENCH_MODEL_ANS, "r") as f:                                                                                                                                                                                          
        ans_data = json.load(f)                                                                                                                                                                                                       
        for item in ans_data:                                                                                                                                                                                                         
            if item.get("id") == question_id:                                                                                                                                                                                         
                model_answer = item.get("predict", "")                                                                                                                                                                                
                break                                                                                                                                                                                                                 
                                                                                                                                                                                                                                        
    return (                                                                                                                                                                                                                          
        image_path,                                                                                                                                                                                                                   
        f"A chat between a curious user and an artificial intelligence assistant. The assistant gives helpful, detailed, and polite answers to the user's questions. USER: <image>\n{question} ASSISTANT: {model_answer}",            
    )                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                        
