# 3. MMMU                                                                                                                                                                                                                             
# -------------------------------------------------------------------------                                                                                                                                                           
def prep_prompt_mmmu(question_id: str, model_id: str) -> tuple[str, str]:                                                                                                                                                             
    """Prepares a prompt for MMMU college-level multidisciplinary questions."""                                                                                                                                                       
    MMMU_MODEL_ANS = f"/g/home/orachat.c/project/MLLM/TokenPacker/playground/data/eval/MMMU/answers/{model_id}/merge.jsonl"                                                                                                           
    image_root = "/g/home/orachat.c/project/MLLM/TokenPacker/playground/data/eval/MMMU/images"                                                                                                                                        
                                                                                                                                                                                                                                        
    question, image_path, model_answer = "", "", ""                                                                                                                                                                                   
    with open(MMMU_MODEL_ANS, "r") as f:                                                                                                                                                                                              
        for line in f:                                                                                                                                                                                                                
            item = json.loads(line)                                                                                                                                                                                                   
            if str(item.get("id")) == str(question_id):                                                                                                                                                                               
                question = item.get("question", item.get("prompt", ""))                                                                                                                                                               
                img_name = item.get("image", f"{question_id}.png")                                                                                                                                                                    
                image_path = f"{image_root}/{img_name}"                                                                                                                                                                               
                model_answer = item.get("parsed_pred", item.get("response", item.get("text", "")))                                                                                                                                    
                break                                                                                                                                                                                                                 
                                                                                                                                                                                                                                        
    return (                                                                                                                                                                                                                          
        image_path,                                                                                                                                                                                                                   
        f"A chat between a curious user and an artificial intelligence assistant. The assistant gives helpful, detailed, and polite answers to the user's questions. USER: <image>\n{question} ASSISTANT: {model_answer}",            
    )                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                        
# -------------------------------------------------------------------------                                                                                                                                                           
# 4. MMBench                                                                                                                                                                                                                          
# -------------------------------------------------------------------------                                                                                                                                                           
def prep_prompt_mmbench(question_id: int, model_id: str) -> tuple[str, str]:                                                                                                                                                          
    """Prepares a prompt for MMBench questions."""                                                                                                                                                                                    
    MMBENCH_TSV_PATH = "/g/home/orachat.c/project/MLLM/TokenPacker/playground/data/eval/mmbench/mmbench_dev_20230712.tsv"                                                                                                             
    MMBENCH_MODEL_ANS = f"/g/home/orachat.c/project/MLLM/TokenPacker/playground/data/eval/mmbench/answers/mmbench_dev_20230712/{model_id}.jsonl"                                                                                      
    image_root = "/g/home/orachat.c/project/MLLM/TokenPacker/playground/data/eval/mmbench/images"                                                                                                                                     
                                                                                                                                                                                                                                        
    question, image_path, model_answer = "", "", ""                                                                                                                                                                                   
    df = pd.read_csv(MMBENCH_TSV_PATH, sep="\t")                                                                                                                                                                                      
    row = df[df["index"] == question_id]                                                                                                                                                                                              
    if not row.empty:                                                                                                                                                                                                                 
        r = row.iloc[0]                                                                                                                                                                                                               
        question = (                                                                                                                                                                                                                  
            f"{r['question']}\n"                                                                                                                                                                                                      
            f"A. {r['A']}\nB. {r['B']}\nC. {r['C']}\nD. {r['D']}\n"                                                                                                                                                                   
            "Answer with the option's letter from the given choices directly."                                                                                                                                                        
        )                                                                                                                                                                                                                             
        image_path = f"{image_root}/{question_id}.jpg"                                                                                                                                                                                
                                                                                                                                                                                                                                        
    with open(MMBENCH_MODEL_ANS, "r") as f:                                                                                                                                                                                           
        for line in f:                                                                                                                                                                                                                
            item = json.loads(line)                                                                                                                                                                                                   
            if item.get("question_id") == question_id or item.get("index") == question_id:                                                                                                                                            
                model_answer = item.get("text", item.get("prediction", ""))                                                                                                                                                           
                break                                                                                                                                                                                                                 
                                                                                                                                                                                                                                        
    return (                                                                                                                                                                                                                          
        image_path,                                                                                                                                                                                                                   
        f"A chat between a curious user and an artificial intelligence assistant. The assistant gives helpful, detailed, and polite answers to the user's questions. USER: <image>\n{question} ASSISTANT: {model_answer}",            
    )                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                        
